ResponseCurve headphoneProfileCurve(const std::string& catalogName) {
    for (const auto& e : kHpProfiles) {
        if (catalogName == e.name) {
            ResponseCurve c; c.reserve(static_cast<size_t>(e.count));
            for (int i = 0; i < e.count; ++i) c.push_back({e.data[i * 2], e.data[i * 2 + 1]});
            return c;
        }
    }
    return {};
}

std::vector<std::string> headphoneProfilesWithCurve() {
    std::vector<std::string> names;
    names.reserve(sizeof(kHpProfiles) / sizeof(kHpProfiles[0]));
    for (const auto& e : kHpProfiles) names.emplace_back(e.name);
    return names;
}

